'use strict';

// MODULES //

var bench = require( '@stdlib/bench-harness' );
var isComplex64 = require( '@stdlib/assert-is-complex64' );
var Complex64 = require( '@stdlib/complex-float32-ctor' );
var randu = require( '@stdlib/random-base-randu' );
var pkg = require( './../package.json' ).name;
var conj = require( './../lib' );


// MAIN //

bench( pkg, function benchmark( b ) {
	var values;
	var v;
	var i;

	values = [
		new Complex64( randu(), randu() ),
		new Complex64( randu(), randu() ),
		new Complex64( randu(), randu() )
	];

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v = conj( values[ i%values.length ] );
		if ( typeof v !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isComplex64( v ) ) {
		b.fail( 'should return an object' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});","lineStart":1,"lineEnd":57,"totalLines":57,"truncated":false}},"title":"repos/pc-lib-3456/complex-float32-conj/benchmark/benchmark.js","time":{"start":1783264351676,"end":1783264351681}},"id":"prt_f32d694e6001XRHdVu5DvXwJct","sessionID":"ses_0cd29b669ffelLXBvbcixS88P1","messageID":"msg_f32d68d51001DGmiOKhyryW5w8"}}

